contract KCC20FeeTicket(
    byte[32] stateOwner,
    int stateMode,
    byte[32] utilityKcc20V2TokenId,
    int utilityTokenAmount,
    int v2TemplatePrefixLen,
    int v2TemplateSuffixLen,
    byte[32] v2ExpectedTemplateHash
