        byte[32] feeRecipient;
        int feeBps;
        byte[32] ticker;
        byte[32] name;
        int priceScale;
    }

    function requireRoot() {
        require(mode == MODE_ROOT);
        require(denomination > 0);
    }

    function requireTicket() {
        require(mode == MODE_TICKET);
        require(denomination > 0);
    }

