        ticketOutput(toOwner, ticketOutputIndex);
    }

    entrypoint function burnByOwnerSig(sig ownerSig, int refundOutputIndex) {
        requireTicket();
        require(checkSig(ownerSig, pubkey(owner)));
        require(refundOutputIndex >= 0);
        require(OpAuthOutputCount(this.activeInputIndex) == 0);
        require(tx.outputs[refundOutputIndex].value == tx.inputs[this.activeInputIndex].value);
        require(tx.outputs[refundOutputIndex].scriptPubKey == byte[](new ScriptPubKeyP2PK(pubkey(owner))));
    }

    entrypoint function updateDenominationByOwnerSig(sig ownerSig, int newDenomination, int rootOutputIndex) {
        requireRoot();
        require(checkSig(ownerSig, pubkey(owner)));
        require(newDenomination > 0);
        require(OpAuthOutputCount(this.activeInputIndex) == 1);
        require(OpAuthOutputIdx(this.activeInputIndex, 0) == rootOutputIndex);
        require(tx.outputs[rootOutputIndex].value == tx.inputs[this.activeInputIndex].value);
        validateOutputState(rootOutputIndex, {
            owner: owner,
            mode: MODE_ROOT,
            utilityTokenId: utilityTokenId,
            denomination: newDenomination
        });
    }
}
